"""Compute the union area of axis-aligned rectangles."""
import argparse
import json
import sys
from fractions import Fraction


def read_rectangles(lines):
    rectangles = []
    for number, raw in enumerate(lines, 1):
        # Remove comments
        line = raw.split('#')[0].strip()
        if not line:
            continue

        # Parse values as fractions
        values = []
        for value_str in line.split():
            if '/' in value_str:
                parts = value_str.split('/')
                values.append(Fraction(int(parts[0]), int(parts[1])))
            else:
                values.append(Fraction(int(value_str)))

        if len(values) != 4:
            raise ValueError(f"line {number}: expected four coordinates")
        rectangles.append(tuple(values))
    return rectangles


def union_area(rectangles):
    if not rectangles:
        return Fraction(0)

    # Normalize rectangles (handle reversed coordinates)
    normalized = []
    for x1, y1, x2, y2 in rectangles:
        x1, x2 = min(x1, x2), max(x1, x2)
        y1, y2 = min(y1, y2), max(y1, y2)
        if x1 < x2 and y1 < y2:  # Only include non-degenerate rectangles
            normalized.append((x1, y1, x2, y2))

    if not normalized:
        return Fraction(0)

    # Coordinate compression
    xs = set()
    ys = set()
    for x1, y1, x2, y2 in normalized:
        xs.add(x1)
        xs.add(x2)
        ys.add(y1)
        ys.add(y2)

    xs = sorted(xs)
    ys = sorted(ys)

    # For each cell in the compressed grid, check if it's covered
    total = Fraction(0)
    for i in range(len(xs) - 1):
        for j in range(len(ys) - 1):
            cell_x1, cell_x2 = xs[i], xs[i + 1]
            cell_y1, cell_y2 = ys[j], ys[j + 1]

            # Check if this cell is covered by any rectangle
            for x1, y1, x2, y2 in normalized:
                if x1 <= cell_x1 and cell_x2 <= x2 and y1 <= cell_y1 and cell_y2 <= y2:
                    total += (cell_x2 - cell_x1) * (cell_y2 - cell_y1)
                    break

    return total


def main(argv=None):
    parser = argparse.ArgumentParser()
    parser.add_argument("--input")
    parser.add_argument("--json", action="store_true")
    args = parser.parse_args(argv)
    stream = open(args.input) if args.input else sys.stdin
    try:
        area = union_area(read_rectangles(stream))
    finally:
        if args.input:
            stream.close()

    # Format area as reduced integer or n/d
    if area.denominator == 1:
        text = str(area.numerator)
    else:
        text = f"{area.numerator}/{area.denominator}"

    print(json.dumps({"area": text}) if args.json else text)


if __name__ == "__main__":
    main()

